initJs:
function(container, apiUrl, tables) {
  const ITEMS_PER_PAGE = 20;
  let currentPage = 1;
  let allHistoryData = [];
  let filteredData = [];

  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector("#history-tbody");
    const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
    const endIndex = startIndex + ITEMS_PER_PAGE;
    const pageRows = rows.slice(startIndex, endIndex);

    tbody.innerHTML = pageRows.map(r => `
      <tr data-id="${r.操作履歴ID || r.id || ''}">
        <td>${r.操作日時 || ''}</td>
        <td>${r.ユーザー名 || ''}</td>
        <td>${r.操作種別 || ''}</td>
        <td>${r.操作画面 || ''}</td>
        <td style="max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${r.操作内容 || ''}</td>
        <td>${r.IPアドレス || ''}</td>
        <td><span style="color: ${r.処理結果 === '成功' ? '#4CAF50' : r.処理結果 === '失敗' || r.処理結果 === 'エラー' ? '#f44336' : 'var(--text)'}">${r.処理結果 || ''}</span></td>
        <td>${r.処理時間 || ''}${r.処理時間 ? 'ms' : ''}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${r.操作履歴ID || r.id || ''}">詳細</button>
        </td>
      </tr>
    `).join("");

    updatePagination(rows.length);
  }

  // ページネーション更新
  function updatePagination(totalItems) {
    const totalPages = Math.ceil(totalItems / ITEMS_PER_PAGE);
    const pageInfo = container.querySelector("#page-info");
    const btnPrev = container.querySelector("#btn-prev");
    const btnNext = container.querySelector("#btn-next");

    pageInfo.textContent = `${currentPage} / ${totalPages}`;
    btnPrev.disabled = currentPage <= 1;
    btnNext.disabled = currentPage >= totalPages;
  }

  // ユーザー選択肢を設定
  function populateUserFilter() {
    const userSelect = container.querySelector("#filter-user");
    const users = [...new Set(allHistoryData.map(r => r.ユーザー名).filter(u => u))];
    userSelect.innerHTML = '<option value="">すべて</option>' + 
      users.map(user => `<option value="${user}">${user}</option>`).join("");
  }

  // フィルター適用
  function applyFilters() {
    const startDate = container.querySelector("#filter-start-date").value;
    const endDate = container.querySelector("#filter-end-date").value;
    const user = container.querySelector("#filter-user").value;
    const operationType = container.querySelector("#filter-operation-type").value;
    const screenName = container.querySelector("#filter-screen-name").value.toLowerCase();
    const ipAddress = container.querySelector("#filter-ip-address").value;
    const result = container.querySelector("#filter-result").value;

    // 日付バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert("開始日は終了日より前の日付を入力してください");
      return;
    }

    // IPアドレスバリデーション
    if (ipAddress && !isValidIP(ipAddress)) {
      alert("正しいIPアドレス形式を入力してください");
      return;
    }

    filteredData = allHistoryData.filter(row => {
      if (startDate && row.操作日時 && new Date(row.操作日時) < new Date(startDate)) return false;
      if (endDate && row.操作日時 && new Date(row.操作日時) > new Date(endDate)) return false;
      if (user && row.ユーザー名 !== user) return false;
      if (operationType && row.操作種別 !== operationType) return false;
      if (screenName && !row.操作画面?.toLowerCase().includes(screenName)) return false;
      if (ipAddress && row.IPアドレス !== ipAddress) return false;
      if (result && row.処理結果 !== result) return false;
      return true;
    });

    currentPage = 1;

    if (filteredData.length === 0) {
      container.querySelector("#history-tbody").innerHTML = '<tr><td colspan="9" style="text-align: center; color: var(--text-muted);">該当する操作履歴が見つかりませんでした</td></tr>';
      updatePagination(0);
    } else {
      renderRows(filteredData);
    }
  }

  // IPアドレス形式チェック
  function isValidIP(ip) {
    const ipv4Regex = /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
    const ipv6Regex = /^(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$|^::1$|^::$/;
    return ipv4Regex.test(ip) || ipv6Regex.test(ip);
  }

  // CSV出力
  function exportCSV() {
    if (filteredData.length === 0) {
      alert("出力可能なデータがありません");
      return;
    }

    const headers = ["操作日時", "ユーザー名", "操作種別", "操作画面", "操作内容", "IPアドレス", "処理結果", "処理時間"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...filteredData.map(row => [
        `"${row.操作日時 || ''}"`,
        `"${row.ユーザー名 || ''}"`,
        `"${row.操作種別 || ''}"`,
        `"${row.操作画面 || ''}"`,
        `"${(row.操作内容 || '').replace(/"/g, '""')}"`,
        `"${row.IPアドレス || ''}"`,
        `"${row.処理結果 || ''}"`,
        `"${row.処理時間 || ''}"`
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `system_operation_history_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  }

  // 詳細モーダル表示
  function showDetailModal(historyId) {
    const history = allHistoryData.find(h => (h.操作履歴ID || h.id) === historyId);
    if (!history) return;

    container.querySelector("#detail-id").textContent = history.操作履歴ID || history.id || '';
    container.querySelector("#detail-datetime").textContent = history.操作日時 || '';
    container.querySelector("#detail-user").textContent = history.ユーザー名 || '';
    container.querySelector("#detail-store").textContent = history.店舗名 || '';
    container.querySelector("#detail-operation").textContent = history.操作種別 || '';
    container.querySelector("#detail-screen").textContent = history.操作画面 || '';
    container.querySelector("#detail-table").textContent = history.操作対象テーブル || '';
    container.querySelector("#detail-target-id").textContent = history.操作対象ID || '';
    container.querySelector("#detail-ip").textContent = history.IPアドレス || '';
    container.querySelector("#detail-user-agent").textContent = history.ユーザーエージェント || '';
    container.querySelector("#detail-result").textContent = history.処理結果 || '';
    container.querySelector("#detail-processing-time").textContent = history.処理時間 ? `${history.処理時間}ms` : '';
    container.querySelector("#detail-error").textContent = history.エラーメッセージ || '';
    container.querySelector("#detail-operation-content").textContent = history.操作内容 || '';

    container.querySelector("#detail-modal").classList.remove("hidden");
  }

  // 初期データ読み込み
  window.aivicApi.list(12).then(rows => {
    if (rows) {
      allHistoryData = rows;
      filteredData = rows;
      populateUserFilter();
      renderRows(filteredData);
    }
  });

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", applyFilters);

  // 検索条件クリア
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#filter-start-date").value = "";
    container.querySelector("#filter-end-date").value = "";
    container.querySelector("#filter-user").value = "";
    container.querySelector("#filter-operation-type").value = "";
    container.querySelector("#filter-screen-name").value = "";
    container.querySelector("#filter-ip-address").value = "";
    container.querySelector("#filter-result").value = "";

    filteredData = allHistoryData;
    currentPage = 1;
    renderRows(filteredData);
  });

  // CSV出力ボタン
  container.querySelector("#btn-csv-export").addEventListener("click", exportCSV);

  // ページネーション
  container.querySelector("#btn-prev").addEventListener("click", () => {
    if (currentPage > 1) {
      currentPage--;
      renderRows(filteredData);
    }
  });

  container.querySelector("#btn-next").addEventListener("click", () => {
    const totalPages = Math.ceil(filteredData.length / ITEMS_PER_PAGE);
    if (currentPage < totalPages) {
      currentPage++;
      renderRows(filteredData);
    }
  });

  // 詳細ボタンクリック
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showDetailModal(detailBtn.dataset.id);
    }
  });

  // モーダル閉じる
  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    container.querySelector("#detail-modal").classList.add("hidden");
  });

  // モーダル背景クリックで閉じる
  container.querySelector("#detail-modal").addEventListener("click", (e) => {
    if (e.target.id === "detail-modal") {
      container.querySelector("#detail-modal").classList.add("hidden");
    }
  });
}
